import os
import torch
import random
import numpy as np


class Config:
    """
    Central configuration for the Probabilistic Beam-Search Cascade solution.
    Handles file paths, model hyperparameters, and environment setup.
    """

    # --------------------------------------------------------------------------
    # Directory & File Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_5"
    SUBMISSION_DIR = "./submission"

    # Input Metadata (generated by metadata script)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Output Submission
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Cache Files (Parquet format for efficiency)
    LOCATOR_TRAIN_CACHE = os.path.join(WORKING_DIR, "locator_train.parquet")
    LOCATOR_VAL_CACHE = os.path.join(WORKING_DIR, "locator_val.parquet")
    INFILLER_TRAIN_CACHE = os.path.join(WORKING_DIR, "infiller_train.parquet")
    INFILLER_VAL_CACHE = os.path.join(WORKING_DIR, "infiller_val.parquet")
    TEST_CACHE = os.path.join(WORKING_DIR, "test_cache.parquet")

    # Model Checkpoints
    BEST_LOCATOR_PATH = os.path.join(WORKING_DIR, "best_locator.pth")
    BEST_INFILLER_PATH = os.path.join(WORKING_DIR, "best_infiller.pth")

    # --------------------------------------------------------------------------
    # Model Architectures
    # --------------------------------------------------------------------------
    # Stage 1: Locator
    # DeBERTa-v3 uses disentangled attention, excellent for relative positioning/syntax
    LOCATOR_MODEL_NAME = "microsoft/deberta-v3-base"

    # Stage 2: In-Filler
    # RoBERTa-Large provides high capacity for semantic reconstruction (MLM)
    # Changed to DeBERTa-v3-base to share tokenizer with Locator for efficient inference (tensor splicing)
    INFILLER_MODEL_NAME = "microsoft/deberta-v3-base"

    # --------------------------------------------------------------------------
    # Hyperparameters
    # --------------------------------------------------------------------------
    SEED = 42
    MAX_LEN = 256  # Context window size

    # Dataset Sizes
    # Large training set for robust generalization
    TRAIN_SIZE = 1_000_000
    VAL_SIZE = 20_000
    DEBUG_SIZE = 2000  # Small subset for debugging/testing pipeline

    # Training Configuration
    EPOCHS = 3
    BATCH_SIZE = 32
    # Cite debug_lesson_6: Account for Vocabulary Size in Activation Memory
    TRAIN_BATCH_SIZE = 8
    INF_BATCH_SIZE = 16
    GRAD_ACCUM_STEPS = 1
    NUM_WORKERS = 4

    # Optimization
    LR_LOCATOR = 2e-5
    LR_INFILLER = 1e-5
    WEIGHT_DECAY = 0.01
    WARMUP_RATIO = 0.06
    LABEL_SMOOTHING = 0.1  # Helps locator avoid overconfidence

    # Inference Strategy: Probabilistic Beam Search
    BEAM_WIDTH = 3  # Number of candidate positions to evaluate per sentence

    # Hardware
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    @classmethod
    def initialize(cls):
        """
        Sets up the working environment:
        1. Creates necessary directories.
        2. Sets random seeds for full reproducibility.
        """
        # Create directories
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set seeds
        cls._set_seed(cls.SEED)

        # manage tokenizer parallelism to avoid deadlocks
        os.environ["TOKENIZERS_PARALLELISM"] = "false"

    @staticmethod
    def _set_seed(seed):
        """Helper to set seeds across random, numpy, and torch."""
        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(seed)
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
